@Injectable()
export class DaprConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get bindingMtlDtl(): string {
    return this.configService.get<string>('bindingMtlDtl') ?? '';
  }

  public get bindingMtl(): string {
    return this.configService.get<string>('bindingMtl') ?? '';
  }

  public get bindingSItem(): string {
    return this.configService.get<string>('bindingSItem') ?? '';
  }

  public get bindingShiftDetails(): string {
    return this.configService.get<string>('bindingShiftDetails') ?? '';
  }

  public get bindingStgLoc(): string {
    return this.configService.get<string>('bindingStgLoc') ?? '';
  }

  public get plantHierarchyApiAppId(): string {
    return this.configService.get<string>('plantHierarchyApiAppId') ?? '';
  }

  public onModuleInit(): void {
    this.validateConfiguration();
  }

  private validateConfiguration(): void {
    const context: JobsLogContext = {
      method: 'validateConfiguration',
      service: 'DaprConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'bindingMtlDtl', value: this.bindingMtlDtl },
      { key: 'bindingMtl', value: this.bindingMtl },
      { key: 'bindingSItem', value: this.bindingSItem },
      { key: 'bindingShiftDetails', value: this.bindingShiftDetails },
      { key: 'bindingStgLoc', value: this.bindingStgLoc },
      { key: 'plantHierarchyApiAppId', value: this.plantHierarchyApiAppId },
    ];

    const missingConfigs = requiredConfigs.filter(
      (config) => config.value === undefined,
    );

    if (missingConfigs.length > 0) {
      for (const config of missingConfigs) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
      }
      throw new Error(
        'Configuration error: Some required configurations are not set.',
      );
    }
  }
}

