import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { DaprService } from '@/dapr/dapr.service';

// Environment variables
const bindings = {
  bindingMtl: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_MTL,
  bindingMtlDtl: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_MTL_DTL,
  bindingSItem: process.env.INPUT_BINDINGS_FAURECIA_WIP_DBO_S_ITEM,
  bindingShiftDetails:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_SHIFT_DETAILS_MASTER_DI,
  bindingStgLoc: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_STG_LOC,
  topicPlants: process.env.TOPIC_PLANTS,
};

@Controller('')
export class DaprController {
  public constructor(
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic Topic name
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const event = request.body;
    const plantCode = event?.S_SITE || event?.PLANT;

    const startTime = Date.now();

    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      await this.daprService.handleMessage(event);
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.PROCESSED,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.PROCESSED,
        String(plantCode),
        topic,
      );
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.bindingSItem)
  public async receiveEventItem(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(request, 'receiveEventItem', 's-item');
  }

  @Post(bindings.bindingMtl)
  public async receiveEventMtl(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(request, 'receiveEventMtl', 'material');
  }

  @Post(bindings.bindingMtlDtl)
  public async receiveEventMtlDtl(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventMtlDtl',
      'material-dtl',
    );
  }

  @Post(bindings.bindingStgLoc)
  public async receiveEventStgLoc(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventStgLoc',
      'material-storage-location',
    );
  }

  @Post(bindings.bindingShiftDetails)
  public async receiveEventbindingShiftDetails(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventbindingShiftDetails',
      'shift-details',
    );
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
