  exports: [MessageProcessingService],
})
export class IdocEventsModule {}

import { DiscoveryService } from '@nestjs/core';

export const idocHandler = DiscoveryService.createDecorator<string>();

/** Typed constants for IDoc family identifiers — prevents raw string literals across handlers and EventHub services. */
export const IDOC_FAMILY = {
  bommat: 'BOMMAT',
  matmas: 'MATMAS',
  loirou: 'LOIROU',
} as const;

export type IdocFamilyKey = (typeof IDOC_FAMILY)[keyof typeof IDOC_FAMILY];

export interface IdocHandlerMetadata {
  description: string;
  idocFamily: string;
  version: string;
}

export interface IIdocHandler {
  canHandle(rawPayload: Record<string, unknown>): boolean;
  getMetadata(): IdocHandlerMetadata;
  handle(rawPayload: Record<string, unknown>): Promise<void>;
}

export interface IIdocHandlerRegistry {
  register(key: string, handler: IIdocHandler): void;
  findHandler(
    rawPayload: Record<string, unknown>,
    expectedFamily?: string,
  ): IIdocHandler | undefined;
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { parseEventHubBody } from '@/idoc-integration/common/helpers/json.helper';
import { trackWithTelemetry } from '@/idoc-integration/common/helpers/telemetry.helper';
import { HandlerRegistry } from '@/idoc-integration/idoc-events/handler-registry.service';

@Injectable()
export class MessageProcessingService {
  public constructor(
    private readonly handlerRegistry: HandlerRegistry,
    private readonly customLogger: AppLogger,
  ) {}

  public async processIdoc(
    rawBody: unknown,
    expectedFamily: string,
  ): Promise<void> {
    const context = {
      method: 'processIdoc',
      service: 'MessageProcessingService',
    };

    const parsed = parseEventHubBody(rawBody);
    if (!parsed) {
      this.customLogger.error(
        `Failed to parse IDoc body for ${expectedFamily}: malformed or unsupported payload`,
        context,
      );
      return;
    }

    const handler = this.handlerRegistry.findHandler(parsed, expectedFamily);
    if (!handler) {
      this.customLogger.error(
        `No handler found for IDoc payload on ${expectedFamily} binding`,
        context,
      );
      return;
    }

    try {
      await trackWithTelemetry(
        expectedFamily.toLowerCase(),
        expectedFamily,
        async () => {
          try {
            await handler.handle(parsed);
          } catch (error) {
            if (error instanceof NotFoundException) {
              this.customLogger.warn(
                `NotFoundException during IDoc processing for ${expectedFamily} - prerequisite data missing: ${(error as Error).message}`,
                context,
              );
            } else {
              throw error;
            }
          }
        },
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing IDoc event (${expectedFamily}): ${(error as Error).message}`,
        context,
        error as Error,
      );
    }
  }
}

