import { JobsLogContext } from '@mesx/common-lib';
import { BadRequestException, Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { BOMMAT_V1_CONFIG } from '@/idoc-integration/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc-integration/common/helpers/idoc-handler.helpers';
import { extractIdocFields } from '@/idoc-integration/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc-integration/idoc-events/message-handler.interface';
import { BomPayload } from '@/idoc-integration/modules/bommat/interfaces/bom-payload.interface';
import { BommatIdocService } from '@/idoc-integration/modules/bommat/service/bommat-idoc.service';

@idocHandler(IDOC_FAMILY.bommat)
@Injectable()
export class BommatHandler implements IIdocHandler {
  private static hasText(value: string | null | undefined): boolean {
    return typeof value === 'string' && value.trim().length > 0;
  }

  private static hasValidUomFormat(value: string | null | undefined): boolean {
    const normalizedValue = typeof value === 'string' ? value.trim() : '';
    return normalizedValue.length > 0 && normalizedValue.length <= 3;
  }

  private static isSupportedBommatType(
    rawPayload: Record<string, unknown>,
  ): boolean {
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const idoctyp = ediDc40?.['IDOCTYP'];

    return (
      typeof mestyp === 'string' &&
      /^bommat$/i.test(mestyp.trim()) &&
      typeof idoctyp === 'string' &&
      /^bommat/i.test(idoctyp.trim())
    );
  }

  private static validateRequiredFields(
    payload: BomPayload | null | undefined,
  ): {
    valid: boolean;
    error?: string;
  } {
    if (!payload) {
      return { valid: false, error: 'Payload is empty' };
    }

    if (!BommatHandler.hasText(payload.materialCode)) {
      return {
        valid: false,
        error: 'MATNR (material number) is NULL or empty',
      };
    }

    if (payload.plant === undefined || Number.isNaN(payload.plant)) {
      return { valid: false, error: 'WERKS (plant code) is NULL or empty' };
    }

    if (!BommatHandler.hasText(payload.useType)) {
      return { valid: false, error: 'STLAN (BOM usage type) is NULL or empty' };
    }

    if (!BommatHandler.hasText(payload.alternativeBom)) {
      return {
        valid: false,
        error: 'STLAL (alternative BOM) is NULL or empty',
      };
    }

    if (!BommatHandler.hasText(payload.erpIdentifier)) {
      return { valid: false, error: 'STLNR (BOM number) is NULL or empty' };
    }

    if (!payload.effectiveStartDate) {
      return { valid: false, error: 'DATUV (effective date) is NULL or empty' };
    }

    if (!Array.isArray(payload.items) || payload.items.length === 0) {
      return {
        valid: false,
        error: 'BOM must contain at least one E1STPOM component',
      };
    }

    for (const [index, item] of payload.items.entries()) {
      const itemLabel = `E1STPOM[${index}]`;

      if (!BommatHandler.hasText(item.materialCode)) {
        return {
          valid: false,
          error: `${itemLabel}.IDNRK (component material) is NULL or empty`,
        };
      }

      if (!BommatHandler.hasText(item.quantityUOM)) {
        return {
          valid: false,
          error: `${itemLabel}.MEINS (component UOM) is NULL or empty`,
        };
      }

      if (!BommatHandler.hasValidUomFormat(item.quantityUOM)) {
        return {
          valid: false,
          error: `${itemLabel}.MEINS (component UOM) must be 1 to 3 characters`,
        };
      }

      if (!item.effectiveStartDate) {
        return {
          valid: false,
          error: `${itemLabel}.DATUV (component effective date) is NULL or empty`,
        };
      }

      if (
        item.quantity === null ||
        item.quantity === undefined ||
        Number.isNaN(item.quantity)
      ) {
        return {
          valid: false,
          error: `${itemLabel}.MENGE (component quantity) is NULL or empty`,
        };
      }

      if (item.quantity <= 0) {
        return {
          valid: false,
          error: `${itemLabel}.MENGE must be greater than 0`,
        };
      }
    }

    return { valid: true };
  }

  private readonly metadata: IdocHandlerMetadata = {
    description: 'BOMMAT IDoc handler (BOMMAT01, BOMMAT02, BOMMAT03, etc.)',
    idocFamily: IDOC_FAMILY.bommat,
    version: 'v1',
  };

  public constructor(
    private readonly bommatIdocService: BommatIdocService,
    private readonly customLogger: AppLogger,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'BommatHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const idoctyp = ediDc40?.['IDOCTYP'];
    const result = BommatHandler.isSupportedBommatType(rawPayload);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp}, IDOCTYP=${idoctyp})`,
      context,
    );
    return result;
  }

  private extract(rawPayload: Record<string, unknown>): BomPayload {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'BommatHandler',
    };
    this.customLogger.debug('Starting BOMMAT extraction', context);

    // Extract header data
    const bomPayload = extractIdocFields<BomPayload>(
      rawPayload,
      BOMMAT_V1_CONFIG,
    );

    if (bomPayload.length === 0) {
      throw new BadRequestException('BOMMAT extraction returned no records');
    }

    const payload = { ...bomPayload[0], items: bomPayload[0].items ?? [] };
    const validation = BommatHandler.validateRequiredFields(payload);

    if (!validation.valid) {
      this.customLogger.error(
        `BOMMAT validation failed: ${validation.error}`,
        context,
      );
      throw new BadRequestException(
        `BOMMAT validation failed: ${validation.error}`,
      );
    }

    return payload;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    const context: JobsLogContext = {
      method: 'handle',
      service: 'BommatHandler',
    };
    const bomPayload = this.extract(rawPayload);
    this.customLogger.debug(
      `Processing BOMMAT for plant=${bomPayload.plant}, material=${bomPayload.materialCode}`,
      context,
    );
    await this.bommatIdocService.upsert(bomPayload);
  }
}

export interface BomItemPayload {
  plant: number;
  materialCode: string;
  useType: string;
  quantity: number | null | undefined;
