import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, In, Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { BomDefinition } from '@/idoc-integration/modules/bommat/entities/bom-definition.entity';
import { BomItem } from '@/idoc-integration/modules/bommat/entities/bom-items.entity';
import {
  BomItemPayload,
  BomPayload,
} from '@/idoc-integration/modules/bommat/interfaces/bom-payload.interface';
import { MaterialDefinition } from '@/idoc-integration/modules/common/entities/material-definition.entity';
import { OperationDefinition } from '@/idoc-integration/modules/matmas/entities/operation-definition.entity';

type DateComparisonValue = Date | string | null | undefined;

@Injectable()
export class BommatIdocService {
  private static createLogContext(method: string): JobsLogContext {
    return { method, service: BommatIdocService.name };
  }

  private static getDateComparisonValue(
    value: DateComparisonValue,
  ): number | null {
    if (value === null || value === undefined || value === '') {
      return null;
    }

    const normalizedDate = value instanceof Date ? value : new Date(value);
    const timestamp = normalizedDate.getTime();

    return Number.isNaN(timestamp) ? null : timestamp;
  }

  private static areDatesEqual(
    left: DateComparisonValue,
    right: DateComparisonValue,
  ): boolean {
    return (
      BommatIdocService.getDateComparisonValue(left) ===
      BommatIdocService.getDateComparisonValue(right)
    );
  }

  private static compareStrings(left: string, right: string): number {
    return left.localeCompare(right);
  }

  private static getQuantityComparisonValue(
    quantity: number | string | null | undefined,
  ): string {
    if (quantity === null || quantity === undefined) {
      return '';
    }

    const normalizedQuantity = Number(quantity);
    return Number.isNaN(normalizedQuantity)
      ? String(quantity).trim()
      : normalizedQuantity.toString();
  }

  private static getTextComparisonValue(
    value: string | null | undefined,
  ): string {
    return value?.trim() ?? '';
  }

  private static getBomItemComparisonKey(item: {
    effectiveEndDate?: DateComparisonValue;
    effectiveStartDate?: DateComparisonValue;
    materialDefinitionId: number;
    quantity?: number | string | null;
    quantityUOM?: string | null;
  }): string {
    return [
      item.materialDefinitionId,
      BommatIdocService.getDateComparisonValue(item.effectiveStartDate) ?? '',
      BommatIdocService.getDateComparisonValue(item.effectiveEndDate) ?? '',
      BommatIdocService.getQuantityComparisonValue(item.quantity),
      BommatIdocService.getTextComparisonValue(item.quantityUOM),
    ].join('|');
  }

  private static hasBomHeaderChanges(
    existingDefinition: BomDefinition,
    payload: BomPayload,
  ): boolean {
    return (
      !BommatIdocService.areDatesEqual(
        existingDefinition.effectiveEndDate,
        payload.effectiveEndDate,
      ) ||
      BommatIdocService.getTextComparisonValue(
        existingDefinition.description,
      ) !== BommatIdocService.getTextComparisonValue(payload.description) ||
      BommatIdocService.getTextComparisonValue(
        existingDefinition.erpIdentifier,
      ) !== BommatIdocService.getTextComparisonValue(payload.erpIdentifier) ||
      BommatIdocService.getTextComparisonValue(existingDefinition.erpSource) !==
        BommatIdocService.getTextComparisonValue(payload.erpSource)
    );
  }

  private static hasBomItemChanges(
    existingItems: Array<BomItem>,
    incomingItems: Array<BomItemPayload>,
    componentMaterialsByCode: Map<string, MaterialDefinition>,
  ): boolean {
    if (existingItems.length !== incomingItems.length) {
      return true;
    }

    const existingSignatures = existingItems
      .map((item) => BommatIdocService.getBomItemComparisonKey(item))
      .sort(BommatIdocService.compareStrings);

    const incomingSignatures = incomingItems
      .map((item) => {
        const componentMaterial = componentMaterialsByCode.get(
          item.materialCode,
        ) as MaterialDefinition;

        return BommatIdocService.getBomItemComparisonKey({
          effectiveEndDate: item.effectiveEndDate ?? null,
          effectiveStartDate: item.effectiveStartDate,
          materialDefinitionId: componentMaterial.id,
          quantity: item.quantity ?? null,
          quantityUOM: item.quantityUOM,
        });
      })
      .sort(BommatIdocService.compareStrings);

    return incomingSignatures.some(
      (signature, index) => signature !== existingSignatures[index],
    );
  }

  private static getEffectiveStartDateLabel(
    effectiveStartDate: DateComparisonValue,
  ): string {
    const comparisonValue =
      BommatIdocService.getDateComparisonValue(effectiveStartDate);

    if (comparisonValue === null) {
      return 'n/a';
    }

    return new Date(comparisonValue).toISOString().slice(0, 10);
  }

  private static getBomPersistenceMessage(parameters: {
    existingDefinition: BomDefinition | null;
    hasBomHeaderChanges: boolean;
    hasBomItemChanges: boolean;
    headerMaterialId: number;
    payload: BomPayload;
  }): string {
    const {
      existingDefinition,
      hasBomHeaderChanges,
      hasBomItemChanges,
      headerMaterialId,
      payload,
    } = parameters;

    if (existingDefinition === null) {
      return `No BOM found for materialDefinitionId=${headerMaterialId}, plant=${payload.plant}, useType=${payload.useType}, altBom=${payload.alternativeBom}, effectiveStartDate=${BommatIdocService.getEffectiveStartDateLabel(payload.effectiveStartDate)}; a new BOM header will be created`;
    }

    if (hasBomItemChanges) {
      return `Found matching BOM business key on bomDefinitionId=${existingDefinition.id}; BOM items changed, so a new BOM header and BOM items will be created`;
    }

    if (hasBomHeaderChanges) {
      return `Found matching BOM business key on bomDefinitionId=${existingDefinition.id}; BOM items did not change, so the existing BOM header and items will be updated`;
    }

    return `Found matching BOM business key on bomDefinitionId=${existingDefinition.id}; no BOM or item changes detected, so no action will be taken`;
  }

  private static async findLatestExactBomDefinition(
    manager: EntityManager,
    payload: BomPayload,
    materialDefinitionId: number,
  ): Promise<BomDefinition | null> {
    const bomDefinitionRepo = manager.getRepository(BomDefinition);
    const bomDefinition = await bomDefinitionRepo.findOne({
      order: {
        createdAt: 'DESC',
        id: 'DESC',
      },
      relations: { bomItems: true },
      where: {
        alternativeBom: payload.alternativeBom,
        effectiveStartDate: payload.effectiveStartDate,
        materialDefinitionId,
        plant: payload.plant,
        useType: payload.useType,
      },
    });

    return bomDefinition ?? null;
  }

  private static async resolveComponentMaterials(
    manager: EntityManager,
    items: Array<BomItemPayload>,
    plant: number,
  ): Promise<Map<string, MaterialDefinition>> {
    const componentCodes = [...new Set(items.map((item) => item.materialCode))];
    const componentMaterialRepo = manager.getRepository(MaterialDefinition);

    if (componentCodes.length === 0) {
      return new Map();
    }

    const componentMaterials = await componentMaterialRepo.find({
      where: {
        code: In(componentCodes),
        plant,
      },
    });

    const componentMaterialsByCode = new Map(
      componentMaterials.map((material) => [material.code, material]),
    );

    const missingComponentCodes = componentCodes.filter(
      (code) => !componentMaterialsByCode.has(code),
    );

    if (missingComponentCodes.length > 0) {
      throw new NotFoundException(
        `MaterialDefinition not found in MES for BOM component(s) at plant=${plant}: ${missingComponentCodes.join(', ')}`,
      );
    }

    return componentMaterialsByCode;
  }

  public constructor(
    @InjectRepository(BomDefinition)
    private readonly bomDefinitionRepo: Repository<BomDefinition>,

    @InjectRepository(MaterialDefinition)
    private readonly materialDefinitionRepo: Repository<MaterialDefinition>,

    private readonly customLogger: AppLogger,
  ) {}

  private async resolveHeaderMaterial(
    materialCode: string,
    plant: number,
    context: JobsLogContext,
  ): Promise<MaterialDefinition> {
    const headerMaterial = await this.materialDefinitionRepo.findOne({
      where: { plant, code: materialCode },
    });

    if (!headerMaterial) {
      throw new NotFoundException(
        `MaterialDefinition not found in MES for BOM header MATNR=${materialCode}, plant=${plant}`,
      );
    }

    this.customLogger.debug(
      `Resolved BOM header material MATNR=${materialCode} to materialDefinitionId=${headerMaterial.id}`,
      context,
    );

    return headerMaterial;
  }

  private async saveBomDefinition(
    manager: EntityManager,
    payload: BomPayload,
    materialDefinitionId: number,
    context: JobsLogContext,
    existingDefinition?: BomDefinition | null,
  ): Promise<BomDefinition> {
    const bomDefinitionRepo = manager.getRepository(BomDefinition);

    const bomDefinitionData = {
      alternativeBom: payload.alternativeBom,
      description: payload.description,
      effectiveEndDate: payload.effectiveEndDate ?? null,
      effectiveStartDate: payload.effectiveStartDate,
      erpIdentifier: payload.erpIdentifier,
      erpSource: payload.erpSource,
      materialDefinitionId,
      plant: payload.plant,
      useType: payload.useType,
    };
    const bomDefinition = existingDefinition
      ? bomDefinitionRepo.create({
          ...existingDefinition,
          ...bomDefinitionData,
        })
      : bomDefinitionRepo.create(bomDefinitionData);

    const savedBomDefinition = await bomDefinitionRepo.save(bomDefinition);

    this.customLogger.debug(
      existingDefinition
        ? `Updated BOM header id=${savedBomDefinition.id} for MATNR=${payload.materialCode}, plant=${payload.plant}, useType=${payload.useType}, altBom=${payload.alternativeBom}`
        : `Created BOM header id=${savedBomDefinition.id} for MATNR=${payload.materialCode}, plant=${payload.plant}, useType=${payload.useType}, altBom=${payload.alternativeBom}`,
      context,
    );

    return savedBomDefinition;
  }

  private async syncBomItems(
    manager: EntityManager,
    bomDefinition: BomDefinition,
    existingDefinition: BomDefinition | null,
    componentMaterialsByCode: Map<string, MaterialDefinition>,
    items: Array<BomItemPayload>,
    context: JobsLogContext,
  ): Promise<void> {
    const bomItemRepo = manager.getRepository(BomItem);
    const existingItemsByKey = new Map<string, Array<BomItem>>();

    for (const existingItem of existingDefinition?.bomItems ?? []) {
      const comparisonKey =
        BommatIdocService.getBomItemComparisonKey(existingItem);
      const itemsForKey = existingItemsByKey.get(comparisonKey) ?? [];
      itemsForKey.push(existingItem);
      existingItemsByKey.set(comparisonKey, itemsForKey);
    }

    const bomItems = items.map((item) => {
      const componentMaterial = componentMaterialsByCode.get(
        item.materialCode,
      ) as MaterialDefinition;
      const comparisonKey = BommatIdocService.getBomItemComparisonKey({
        effectiveEndDate: item.effectiveEndDate ?? null,
        effectiveStartDate: item.effectiveStartDate,
        materialDefinitionId: componentMaterial.id,
        quantity: item.quantity ?? null,
        quantityUOM: item.quantityUOM,
      });
      const existingItem = existingItemsByKey.get(comparisonKey)?.shift();

      if (existingDefinition && existingItem === undefined) {
        throw new Error(
          `Existing BOM item could not be matched for bomDefinitionId=${bomDefinition.id}, componentMaterialDefinitionId=${componentMaterial.id}`,
        );
      }

      return bomItemRepo.create({
        ...(existingItem ? { id: existingItem.id } : {}),
        bomDefinitionId: bomDefinition.id,
        effectiveEndDate: item.effectiveEndDate ?? null,
        effectiveStartDate: item.effectiveStartDate,
        materialDefinitionId: componentMaterial.id,
        plant: bomDefinition.plant,
        quantity: item.quantity ?? null,
        quantityUOM: item.quantityUOM,
        useType: item.useType,
      });
    });

    await bomItemRepo.save(bomItems);

    const updatedItemCount = bomItems.filter((item) => item.id).length;
    const insertedItemCount = bomItems.length - updatedItemCount;

    this.customLogger.debug(
      `Synchronized ${bomItems.length} BOM item(s) for bomDefinitionId=${bomDefinition.id} (${updatedItemCount} updated, ${insertedItemCount} inserted)`,
      context,
    );
  }

  private async linkOperationDefinition(
    manager: EntityManager,
    bomDefinitionId: number,
    materialDefinitionId: number,
    payload: BomPayload,
    context: JobsLogContext,
  ): Promise<void> {
    const updateResult = await manager
      .getRepository(OperationDefinition)
      .createQueryBuilder()
      .update(OperationDefinition)
      .set({ bomDefinitionId })
      .where('plant = :plant', { plant: payload.plant })
      .andWhere('material_definition_id = :materialDefinitionId', {
        materialDefinitionId,
      })
      .andWhere('use_type = :useType', { useType: payload.useType })
      .andWhere('alternative_bom = :alternativeBom', {
        alternativeBom: payload.alternativeBom,
      })
      .andWhere('effective_start_date = :effectiveStartDate', {
        effectiveStartDate: payload.effectiveStartDate,
      })
      .execute();

    if (updateResult.affected) {
      this.customLogger.debug(
        `Updated ${updateResult.affected} operation_definition record(s) with bomDefinitionId=${bomDefinitionId}`,
        context,
      );
    } else {
      this.customLogger.warn(
        `No operation_definition found to link for (plant=${payload.plant}, material=${payload.materialCode}, useType=${payload.useType}, altBom=${payload.alternativeBom})`,
        context,
      );
    }
  }

  public async upsert(payload: BomPayload): Promise<void> {
    const context = BommatIdocService.createLogContext('upsert');

    try {
      const headerMaterial = await this.resolveHeaderMaterial(
        payload.materialCode,
        payload.plant,
        context,
      );

      await this.bomDefinitionRepo.manager.transaction(async (manager) => {
        const componentMaterialsByCode =
          await BommatIdocService.resolveComponentMaterials(
            manager,
            payload.items,
            payload.plant,
          );

        const existingDefinition =
          await BommatIdocService.findLatestExactBomDefinition(
            manager,
            payload,
            headerMaterial.id,
          );
        const hasBomItemChanges = existingDefinition
          ? BommatIdocService.hasBomItemChanges(
              existingDefinition.bomItems ?? [],
              payload.items,
              componentMaterialsByCode,
            )
          : false;
        const hasBomHeaderChanges = existingDefinition
          ? BommatIdocService.hasBomHeaderChanges(existingDefinition, payload)
          : false;
        const shouldCreateNewBom =
          existingDefinition === null || hasBomItemChanges;
        const persistenceMessage = BommatIdocService.getBomPersistenceMessage({
          existingDefinition,
          hasBomHeaderChanges,
          hasBomItemChanges,
          headerMaterialId: headerMaterial.id,
          payload,
        });

        this.customLogger.debug(persistenceMessage, context);

        if (
          existingDefinition !== null &&
          !hasBomItemChanges &&
          !hasBomHeaderChanges
        ) {
          return;
        }

        const savedBomDefinition = await this.saveBomDefinition(
          manager,
          payload,
          headerMaterial.id,
          context,
          shouldCreateNewBom ? null : existingDefinition,
        );

        await this.syncBomItems(
          manager,
          savedBomDefinition,
          shouldCreateNewBom ? null : existingDefinition,
          componentMaterialsByCode,
          payload.items,
          context,
        );

        await this.linkOperationDefinition(
          manager,
          savedBomDefinition.id,
          headerMaterial.id,
          payload,
          context,
        );
      });
    } catch (error: unknown) {
      const safeError =
        error instanceof Error ? error : new Error(String(error));

      this.customLogger.error(
        `Error upserting BOM: ${safeError.message}`,
        context,
        safeError,
      );
      throw safeError;
    }
  }
}

