import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { LOIROU_V1_CONFIG } from '@/idoc-integration/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc-integration/common/helpers/idoc-handler.helpers';
import { extractIdocFields } from '@/idoc-integration/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc-integration/idoc-events/message-handler.interface';
import { LoirouPayload } from '@/idoc-integration/modules/loirou/interfaces/loirou-payload.interface';
import { LoirouIdocService } from '@/idoc-integration/modules/loirou/service/loirou-idoc.service';

@idocHandler(IDOC_FAMILY.loirou)
@Injectable()
export class LoirouHandler implements IIdocHandler {
  private readonly metadata: IdocHandlerMetadata = {
    description: 'LOIROU IDoc handler (LOIROU02, ZLOIROU2, etc.)',
    idocFamily: IDOC_FAMILY.loirou,
    version: 'v1',
  };

  private readonly familyPattern = /loirou/i; // Matches MESTYP values like 'LOIROU', 'LOIROU02', 'ZLOIROU2'. i flag makes it case-insensitive.

  public constructor(
    private readonly loirouIdocService: LoirouIdocService,
    private readonly customLogger: AppLogger,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'LoirouHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const result =
      typeof mestyp === 'string' && this.familyPattern.test(mestyp);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp})`,
      context,
    );
    return result;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  private extract(rawPayload: Record<string, unknown>): LoirouPayload {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'LoirouHandler',
    };
    this.customLogger.debug('Starting LOIROU extraction', context);

    // Extract items with header values as context
    const loirouPayload = extractIdocFields<LoirouPayload>(
      rawPayload,
      LOIROU_V1_CONFIG,
    );

    if (loirouPayload.length === 0) {
      throw new Error('LOIROU payload extraction returned no records');
    }

    return loirouPayload[0];
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    const payload = this.extract(rawPayload);

    await this.loirouIdocService.upsert(payload);
  }
}

