import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

import { AppLogger } from '@/common/logger/app-logger';
import { MaterialDefinition } from '@/idoc-integration/modules/common/entities/material-definition.entity';
import { OperationSegment } from '@/idoc-integration/modules/loirou/entities/operation-segment.entity';
import {
  LoirouPayload,
  OperationSegmentPayload,
} from '@/idoc-integration/modules/loirou/interfaces/loirou-payload.interface';
import { OperationDefinition } from '@/idoc-integration/modules/matmas/entities/operation-definition.entity';

@Injectable()
export class LoirouIdocService {
  private static createLogContext(method: string): JobsLogContext {
    return { method, service: LoirouIdocService.name };
  }

  private static isPayloadValid(payload?: LoirouPayload): boolean {
    return Boolean(
      payload?.materialCode &&
        payload?.plnnr &&
        Array.isArray(payload?.operationSegments),
    );
  }

  private static buildSegmentRow(
    segment: OperationSegmentPayload,
    plant: number,
    operationDefinitionId: number,
  ): Omit<Partial<OperationSegment>, 'operationDefinition'> {
    return {
      description: segment.description,
      durationUOM: segment.durationUOM,
      effectiveEndDate: segment.effectiveEndDate,
      effectiveStartDate: segment.effectiveStartDate,
      equipment: segment.equipment,
      erpIdentifier: segment.erpIdentifier,
      hlogDuration: segment.hlogDuration,
      hmacDuration: segment.hmacDuration,
      hmodDuration: segment.hmodDuration,
      operationDefinitionId,
      operationNB: segment.operationNB,
      operationType: segment.operationType,
      plant,
      prodTime: segment.prodTime,
      updatedAt: (() => 'SYSUTCDATETIME()') as unknown as Date,
    };
  }

  public constructor(
    @InjectRepository(OperationDefinition)
    private readonly operationDefinitionRepo: Repository<OperationDefinition>,

    @InjectRepository(OperationSegment)
    private readonly operationSegmentRepo: Repository<OperationSegment>,

    private readonly logger: AppLogger,
  ) {}

  private async resolveOperationDefinition(
    groupCounter: string,
    materialCode: string,
    plant: number,
    plnnr: string,
  ): Promise<OperationDefinition | null> {
    return this.operationDefinitionRepo
      .createQueryBuilder('op')
      .innerJoin(
        MaterialDefinition,
        'mat',
        'mat.id = op.material_definition_id AND mat.plant = op.plant',
      )
      .where('mat.code = :materialCode', {
        materialCode,
      })
      .andWhere('op.task_group_id = :plnnr', {
        plnnr,
      })
      .andWhere('op.group_counter = :groupCounter', {
        groupCounter,
      })
      .andWhere('op.plant = :plant', { plant })
      .getOne();
  }

  public async upsert(payload: LoirouPayload): Promise<void> {
    const context = LoirouIdocService.createLogContext('upsert');

    if (!LoirouIdocService.isPayloadValid(payload)) {
      this.logger.error('Invalid LOIROU payload', context);
      return;
    }

    const plant = Number.parseInt(payload.plant, 10);
    try {
      const segmentRowsOrNull = await Promise.all(
        payload.operationSegments.map(async (segment) => {
          if (!segment.operationNB) {
            this.logger.warn(
              'Skipping LOIROU operation without VORNR',
              context,
            );
            return null;
          }

          const groupCounter = (segment.groupCounter || '').trim();
          if (!groupCounter) {
            this.logger.warn(
              `Skipping LOIROU operation VORNR=${segment.operationNB}: missing PLNAL`,
              context,
            );
            return null;
          }

          const operationDefinition = await this.resolveOperationDefinition(
            groupCounter,
            payload.materialCode,
            plant,
            payload.plnnr,
          );

          if (!operationDefinition) {
            this.logger.warn(
              `No OperationDefinition found for MATNR=${payload.materialCode}, PLNNR=${payload.plnnr}, PLNAL=${groupCounter}`,
              context,
            );
            return null;
          }

          return LoirouIdocService.buildSegmentRow(
            segment,
            plant,
            operationDefinition.id,
          );
        }),
      );

      const segmentRows = segmentRowsOrNull.filter(
        (row): row is Omit<Partial<OperationSegment>, 'operationDefinition'> =>
          row !== null,
      );

      if (segmentRows.length === 0) {
        this.logger.warn(
          'No OperationSegments to upsert after validation',
          context,
        );
        return;
      }

      await this.operationSegmentRepo.upsert(segmentRows, {
        conflictPaths: ['operationDefinitionId', 'plant', 'operationNB'],
      });
    } catch (error: unknown) {
      const safeError =
        error instanceof Error ? error : new Error(String(error));

      this.logger.error(
        `Error while processing LOIROU IDOC: ${safeError.message}`,
        context,
        safeError,
      );
    }
  }
}

