import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { MATMAS_V1_CONFIG } from '@/idoc-integration/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc-integration/common/helpers/idoc-handler.helpers';
import { extractIdocFields } from '@/idoc-integration/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc-integration/idoc-events/message-handler.interface';
import {
  MATMAS_MESTYP,
  MatmasIdoc,
} from '@/idoc-integration/modules/matmas/dto/matmas.dto';
import { MatmasPayload } from '@/idoc-integration/modules/matmas/interfaces/matmas-payload.interface';
import { MatmasIdocService } from '@/idoc-integration/modules/matmas/service/matmas-idoc.service';

@idocHandler(IDOC_FAMILY.matmas)
@Injectable()
export class MatmasHandler implements IIdocHandler {
  private static extractIdoc(
    rawPayload: Record<string, unknown>,
  ): MatmasIdoc | undefined {
    for (const key of Object.keys(rawPayload)) {
      const wrapper = rawPayload[key] as Record<string, unknown> | undefined;
      const idoc = wrapper?.IDOC as Record<string, unknown> | undefined;
      const ediDc40 = idoc?.EDI_DC40 as Record<string, unknown> | undefined;
      if (ediDc40?.MESTYP === MATMAS_MESTYP) {
        return wrapper?.IDOC as MatmasIdoc;
      }
    }
    return undefined;
  }

  private readonly metadata: IdocHandlerMetadata = {
    description: 'MATMAS IDoc handler (MATMAS02, MATMAS03, MATMAS05, etc.)',
    idocFamily: IDOC_FAMILY.matmas,
    version: 'v1',
  };

  private readonly familyPattern = /matmas/i; // Matches MESTYP values like 'MATMAS', 'MATMAS02', 'MATMAS03'. i flag makes it case-insensitive.

  public constructor(
    private readonly matmasIdocService: MatmasIdocService,
    private readonly customLogger: AppLogger,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'MatmasHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const result =
      typeof mestyp === 'string' && this.familyPattern.test(mestyp);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp})`,
      context,
    );
    return result;
  }

  private extract(rawPayload: Record<string, unknown>): Array<MatmasPayload> {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'MatmasHandler',
    };
    this.customLogger.debug('Starting MATMAS extraction', context);

    // Extract items with header values as context
    const plantData = extractIdocFields<MatmasPayload>(
      rawPayload,
      MATMAS_V1_CONFIG,
    );

    if (plantData.length === 0) {
      throw new Error('MATMAS extraction returned no records');
    }

    return plantData;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    const payloads = this.extract(rawPayload);

    await Promise.all(
      payloads.map((matmasPayload) => {
        return this.matmasIdocService.upsert(matmasPayload);
      }),
    );
  }
}

