import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { MaterialDefinition } from '@/idoc-integration/modules/common/entities/material-definition.entity';
import { MaterialDescriptionByLanguage } from '@/idoc-integration/modules/matmas/entities/material-description-by-language.entity';
import { OperationDefinition } from '@/idoc-integration/modules/matmas/entities/operation-definition.entity';
import { MatmasPayload } from '@/idoc-integration/modules/matmas/interfaces/matmas-payload.interface';

@Injectable()
export class MatmasIdocService {
  private static createLogContext(method: string): JobsLogContext {
    return { method, service: MatmasIdocService.name };
  }

  public constructor(
    @InjectRepository(MaterialDefinition)
    private readonly materialDefinitionRepo: Repository<MaterialDefinition>,

    private readonly customLogger: AppLogger,
  ) {}

  public async upsert(payload: MatmasPayload): Promise<void> {
    const method = 'upsert';
    const context = MatmasIdocService.createLogContext(method);

    if (!payload) {
      this.customLogger.error('MATMAS payload is empty', context);
      return;
    }

    try {
      const {
        languageDefinitions: languageItems,
        materialDefinition: materialData,
        operationDefinitions: operationItems,
      } = payload;

      await this.materialDefinitionRepo.manager.transaction(
        async (transactionalEntityManager) => {
          const languageDefinitionRepo =
            transactionalEntityManager.getRepository(
              MaterialDescriptionByLanguage,
            );
          const materialDefinitionRepo =
            transactionalEntityManager.getRepository(MaterialDefinition);
          const operationDefinitionRepo =
            transactionalEntityManager.getRepository(OperationDefinition);

          await materialDefinitionRepo.upsert(
            { ...materialData, updatedAt: () => 'SYSUTCDATETIME()' },
            {
              conflictPaths: ['plant', 'code'],
            },
          );

          const materialDefinition = await materialDefinitionRepo.findOne({
            where: {
              plant: materialData.plant,
              code: materialData.code,
            },
          });

          if (!materialDefinition) {
            throw new Error(
              `MaterialDefinition not found after upsert (plant=${materialData.plant}, code=${materialData.code})`,
            );
          }

          if (languageItems?.length) {
            await languageDefinitionRepo.upsert(
              languageItems.map((item) => ({
                ...item,
                materialDefinitionId: materialDefinition.id,
                plant: materialData.plant,
                updatedAt: () => 'SYSUTCDATETIME()',
              })),
              {
                conflictPaths: ['materialDefinitionId', 'code'],
              },
            );
          }

          if (operationItems?.length) {
            await operationDefinitionRepo.upsert(
              operationItems.map((item) => ({
                ...item,
                materialDefinitionId: materialDefinition.id,
                updatedAt: () => 'SYSUTCDATETIME()',
              })),
              {
                conflictPaths: [
                  'materialDefinitionId',
                  'plant',
                  'useType',
                  'alternativeBom',
                ],
              },
            );
          }
        },
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting MATMAS: ${error.message}`,
        context,
        error,
      );
    }
  }
}

import { loadEnvironment } from './bootstrap/environment';

/**
 *
 */
async function main(): Promise<void> {
  loadEnvironment();
  const telemetry = await import('./bootstrap/telemetry');
  await telemetry.initTelemetry();
  const startAppModule = await import('./bootstrap/start-app');
  await startAppModule.startApp();
