    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('shiftDetails.c')
  private async create(payload: ShiftDetails): Promise<void> {
    const context = {
      method: 'create',
      object: `${payload.plant}-${payload.idRow}`,
      plant: payload.plant,
      service: 'ShiftDetailsService',
    };

    if (!payload) {
      this.customLogger.verbose('Payload is empty', context);
      return;
    }

    const startTime = Date.now();
    try {
      await this.shiftDetailsRepo.upsert(
        { ...payload, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['idRow', 'plant'] },
      );
      const sqlDuration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'shift-details',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'shift-details',
      );
