import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';

import { StorageLocation } from '@/modules/storage-location/storage-location.entity';

@Injectable()
export class StorageLocationService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: StorageLocationService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(StorageLocation)
    private readonly storageLocationRepository: Repository<StorageLocation>,
    private readonly customLogger: AppLogger,
  ) {}

  private async handlePayload(payload: StorageLocation): Promise<void> {
    // Utility function to avoid duplicate lines error from Sonar Qube
    const { ...storageLocationData } = payload;
    const { tpaLocation, poolstock } = storageLocationData;

    if (poolstock) {
      storageLocationData.type = 'POOL';
    } else if (tpaLocation) {
      storageLocationData.type = 'TPA';
    } else {
      storageLocationData.type = 'SHOP';
    }

    const startTime = Date.now();
    await this.storageLocationRepository.upsert(
      { ...storageLocationData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
      { conflictPaths: ['storageLocationId', 'plant'] },
    );
    const sqlDuration = Date.now() - startTime;
    telemetryMetrics.trackEventProcessingDuration(
      sqlDuration,
      PROCESSING_STATUS.SQL,
      String(payload.plant),
      'storage-location',
    );
    telemetryMetrics.trackEventProcessed(
      PROCESSING_STATUS.SQL,
      String(payload.plant),
      'storage-location',
    );
  }

  @OnEvent('storageLocation.c')
  private async create(payload: StorageLocation): Promise<void> {
    const context = StorageLocationService.createLogContext(
      'create',
      Number(payload?.plant),
      payload?.storageLocationId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      await this.handlePayload(payload);
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base : ${error.message}`,
        context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('storageLocation.u')
  private async updateByProductionIdAndPlant(
    payload: StorageLocation,
  ): Promise<void> {
    const context = StorageLocationService.createLogContext(
      'updateByProductionIdAndPlant',
      Number(payload?.plant),
      payload?.storageLocationId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    try {
      await this.handlePayload(payload);
    } catch (error) {
      this.customLogger.error(
        `Error updating storageLocation: ${error.message}`,
        context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('storageLocation.r')
  private async readSnapshot(payload: StorageLocation): Promise<void> {
    const context = StorageLocationService.createLogContext(
      'readSnapshot',
      Number(payload?.plant),
      payload?.storageLocationId,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      await this.handlePayload(payload);
    } catch (error) {
      this.customLogger.error(
        `Error updating Storage location: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

